// E-Ticaret Sistemi - Ana Giriş Noktası
// Main Entry Point

// Modelleri içe aktar
"src/models/user.hudhud" 使用;
"src/models/product.hudhud" 使用;
"src/models/order.hudhud" 使用;

// Servisleri içe aktar
"src/services/auth.hudhud" 使用;
"src/services/payment.hudhud" 使用;
"src/services/notification.hudhud" 使用;

// Yardımcı クラスları içe aktar
"src/utils/validation.hudhud" 使用;
"src/utils/formatting.hudhud" 使用;

印刷("============================================================");
印刷("E-Ticaret Sistemi - Modüler Mimari Demo");
印刷("============================================================\n");

// Servis örnekleri oluştur
変数 authService = 新規 AuthService();
変数 paymentService = 新規 PaymentService();
変数 notificationService = 新規 NotificationService();

印刷("1️⃣  KULLANICI KAYDI");
印刷("─────────────────────────────────────────────────────────\n");

// Yeni 使用ıcı oluştur
変数 newUser = 新規 User("Davut Süleyman", "davut@example.com", "güvenli123");
印刷("Kullanıcı oluşturuldu: " + newUser.bilgi());

// Email 真la
もし (Validation.email(newUser.email)) {
    印刷("✓ Email geçerli: " + newUser.email);
} そうでなければ {
    印刷("✗ Email geçersiz");
}

// Kullanıcıyı kaydet
変数 authResult = authService.register(newUser);
もし (authResult.success) {
    印刷("✓ " + authResult.message + " (ID: " + authResult.userId + ")");

    // Hoş geldin bildirimi
    notificationService.send(
        newUser.email,
        "Hoş Geldiniz!",
        "Aramıza hoş geldiniz, " + newUser.name
    );
}

印刷("\n2️⃣  ÜRÜN OLUŞTURMA");
印刷("─────────────────────────────────────────────────────────\n");

// Ürün oluştur
変数 product = 新規 Product("MacBook Pro M3", 45000, 10, "Elektronik");
印刷("Ürün oluşturuldu: " + product.bilgi());

// Fiyat 真la
もし (Validation.price(product.price)) {
    印刷("✓ Fiyat geçerli: " + Formatting.currency(product.price, "TRY"));
}

// Stok kontrolü
もし (product.inStock()) {
    印刷("✓ Ürün stokta mevcut");
} そうでなければ {
    印刷("✗ Ürün stokta yok");
}

印刷("\n3️⃣  SİPARİŞ OLUŞTURMA");
印刷("─────────────────────────────────────────────────────────\n");

// Sipariş oluştur
変数 order = 新規 Order(
    newUser.id,
    product.id,
    1,
    product.price
);
印刷("Sipariş oluşturuldu: " + order.bilgi());

印刷("\n4️⃣  ÖDEME İŞLEMİ");
印刷("─────────────────────────────────────────────────────────\n");

// Ödeme işle
変数 paymentResult = paymentService.process(
    order.id,
    order.totalPrice,
    "credit_card"
);

もし (paymentResult.success) {
    印刷("✓ " + paymentResult.message);
    印刷("  İşlem No: " + paymentResult.transactionId);
    印刷("  Tutar: " + Formatting.currency(paymentResult.amount, "TRY"));
    印刷("  Yöntem: " + paymentResult.method);

    // Siparişi onayla
    order.confirm();
    印刷("✓ Sipariş onaylandı: " + order.status);

    // Sipariş onay bildirimi
    notificationService.send(
        newUser.email,
        "Siparişiniz Onaylandı",
        "Sipariş numaranız: " + order.id + " - Toplam: " + Formatting.currency(order.totalPrice, "TRY")
    );
} そうでなければ {
    印刷("✗ Ödeme başarısız: " + paymentResult.error);
}

印刷("\n============================================================");
印刷("✓ E-Ticaret sistemi demo tamamlandı!");
印刷("✓ Modüler, ölçeklenebilir ve bakımı kolay mimari");
印刷("============================================================");

