            token: "token_" + Math.floor(Math.random() * 1000),
            message: "Giriş başarılı"
        };
    }

    関数 logout(token) {
        戻る { success: 真 };
    }

    関数 verifyToken(token) {
        戻る { valid: 真, userId: "user_123" };
    }
}

