// Formatting Utilities - Formatlama Fonksiyonları

クラス Formatting {
    静的 関数 currency(amount, currency) {
        もし (currency == "TRY") {
            戻る amount + " ₺";
        } そうでなければ {
            もし (currency == "USD") {
                戻る "$" + amount;
            } そうでなければ {
                もし (currency == "EUR") {
                    戻る "€" + amount;
                } そうでなければ {
                    戻る amount + " " + currency;
                }
            }
        }
    }

    静的 関数 date(date) {
        戻る date;
    }

    静的 関数 phone(phone) {
        // (555) 123-4567 formatı
        戻る "(" + phone + ")";
    }

    静的 関数 number(num) {
        // 1,234,567 formatı
        戻る num;
    }
}

